import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第三卦 屯 水雷屯 坎上震下","description":"周易 - 第三卦 屯 水雷屯 坎上震下","frontmatter":{"title":"第三卦 屯 水雷屯 坎上震下","description":"周易 - 第三卦 屯 水雷屯 坎上震下"},"headers":[],"relativePath":"zh/classics/zhouyi/004.md","filePath":"zh/classics/zhouyi/004.md"}'),l={name:"zh/classics/zhouyi/004.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="屯" tabindex="-1">屯 <a class="header-anchor" href="#屯" aria-label="Permalink to “屯”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>元，亨，利，贞，勿用，有攸往，利建侯。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>屯，刚柔始交而难生，动乎险中，大亨贞。雷雨之动满盈，天造草昧，宜建侯而不宁。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>云，雷，屯；君子以经纶。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>磐桓；利居贞，利建侯。象曰：虽磐桓，志行正也。以贵下贱，大得民也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>屯如(辶颤)如，乘马班如。匪寇婚媾，女子贞不字，十年乃字。象曰：六二之难，乘 刚也。十年乃字，反常也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>既鹿无虞，惟入于林中，君子几不如舍，往吝。象曰：既鹿无虞，以纵禽也。君子舍之，往吝穷也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>乘马班如，求婚媾，无不利。象曰：求而往，明也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>屯其膏，小贞吉，大贞凶。象曰：屯其膏，施未光也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>乘马班如，泣血涟如。象曰：泣血涟如，何可长也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
